import{_ as i,l as a,o as n,b as o,q as h,m as s,d as t,f as l}from"./chunks/framework.Tf23FRXt.js";const g=JSON.parse('{"title":"周边衍生","description":"","frontmatter":{},"headers":[{"level":2,"title":"光之回忆录","slug":"光之回忆录","link":"#光之回忆录","children":[]},{"level":2,"title":"周边漫画","slug":"周边漫画","link":"#周边漫画","children":[{"level":3,"title":"迷途的异乡人","slug":"迷途的异乡人","link":"#迷途的异乡人","children":[]},{"level":3,"title":"咲与最终幻想XIV","slug":"咲与最终幻想xiv","link":"#咲与最终幻想xiv","children":[]},{"level":3,"title":"最终幻想 XIV 私立艾欧泽亚学园","slug":"最终幻想-xiv-私立艾欧泽亚学园","link":"#最终幻想-xiv-私立艾欧泽亚学园","children":[]}]},{"level":2,"title":"光之老爹","slug":"光之老爹","link":"#光之老爹","children":[]},{"level":2,"title":"玩家自制电影","slug":"玩家自制电影","link":"#玩家自制电影","children":[]},{"level":2,"title":"纪录片","slug":"纪录片","link":"#纪录片","children":[]},{"level":2,"title":"其他","slug":"其他","link":"#其他","children":[]}],"relativePath":"topic/other.htm.md","filePath":"topic/other.md","lastUpdated":1791098838000}'),p={name:"topic/other.htm.md"};function d(c,e,f,m,b,_){const r=a("IncludePage");return n(),o("div",null,[e[0]||(e[0]=h('<h1 id="周边衍生" tabindex="-1">周边衍生</h1><p>以下是一些游戏相关的影音文内容。</p><h2 id="光之回忆录" tabindex="-1">光之回忆录</h2><p>官方撰写的短篇故事合辑，以各篇章主线 NPC 为主角，讲述他们的一些故事。推荐完成各个版本的主线任务之后再来阅读：</p><blockquote><ul><li><a href="https://actff1.web.sdo.com/project/150702aan/memoir_1.html" target="_blank" rel="noreferrer">第七灵灾回忆录</a></li><li><a href="https://actff1.web.sdo.com/Project/160808Firmament/" target="_blank" rel="noreferrer">苍穹秘话</a></li><li><a href="https://actff1.web.sdo.com/Project/180727Act/index.html" target="_blank" rel="noreferrer">红莲秘话</a></li><li><a href="https://actff1.web.sdo.com/Project/20200817special/index.html" target="_blank" rel="noreferrer">暗影秘话</a>（有国服配音演员诵读）</li><li><a href="https://actff1.web.sdo.com/project/20230826xymihua/index.html" target="_blank" rel="noreferrer">晓月秘话</a>（有国服配音演员诵读）</li><li><a href="https://ff14.huijiwiki.com/wiki/%E6%A8%A1%E6%9D%BF:%E5%8E%86%E5%8F%B2" target="_blank" rel="noreferrer">wiki 链接</a>（有部分国服尚未刊登的内容，以及日本官方出版物《光之回忆录》附加的短篇）</li></ul></blockquote><h2 id="周边漫画" tabindex="-1">周边漫画</h2><h3 id="迷途的异乡人" tabindex="-1">迷途的异乡人</h3><p>最终幻想官方衍生漫画<a href="https://manga.bilibili.com/detail/mc28540" target="_blank" rel="noreferrer">《迷途的异乡人》</a>，和 FF14 一样穿插了 FF 前作的各种细节，编织而成的新的故事。</p><p>憧憬 FF，梦想能制作 FF 而进入史克威尔艾尼克斯工作的正吾，现实里却每天都被与 FF 毫无关系的工作给追着跑。在营业部妹子・夕子的鼓励下，正想要转换一下烦闷的心情时，突然一辆失控的卡车向二人袭来 ——！！下一秒，当正吾醒来之时发现那里居然有 — 莫古力！！？超疗伤！！？？陆行鸟。来到的是一个不属于任何系列的 FF 世界。FF 的狂热粉丝正吾，将在这如何生存！？</p><h3 id="咲与最终幻想xiv" tabindex="-1">咲与最终幻想 XIV</h3><p>《天才麻將少女》十五周年企划，与最终幻想 14 的梦幻联动。 <s>在麻将漫画里看麻将少女们在网游里打麻将的故事（不是）</s></p><ul><li><a href="https://magazine.jp.square-enix.com/mangaup/original/saki_ff/" target="_blank" rel="noreferrer">官方网站阅读（日语）</a></li><li><a href="https://www.bilibili.com/read/readlist/rl366750" target="_blank" rel="noreferrer">玩家汉化版</a></li></ul><h3 id="最终幻想-xiv-私立艾欧泽亚学园" tabindex="-1">最终幻想 XIV 私立艾欧泽亚学园</h3><p>官方干掉同人之作，游戏 NPC 成为了学校的老师和同学，在这所不可思议的学园中发生的故事！</p><p>登场角色均为游戏内重要 NPC，有一定剧透成分，介意者勿点。</p><ul><li><a href="https://magazine.jp.square-enix.com/mangaup/" target="_blank" rel="noreferrer">官方 APP 阅读（日语）</a></li><li><a href="http://manhua.dmzj.com/zzjxssslaozyxy/" target="_blank" rel="noreferrer">玩家汉化版</a></li></ul><h2 id="光之老爹" tabindex="-1">光之老爹</h2><p>光之老爹是一位日本的 FF 玩家在自己的博客上所做的系列连载，讲的是自己<s>为了获得招募好友送的双塔尼亚而</s>安利老爹来玩 FF14，隐藏自己的真实身份在游戏里和老爹一起游戏，在击破双塔尼亚后向老爹公布自己真实身份的壮大孝亲行动 (原话…)。</p><p>这个连载在日本也得到了多方关注，在贵人相助下，成功改编成了电视剧，于 2017 年春季播出。连续剧主人公由千叶雄大和大杉漣主演 (女主角？不存在的)，采用游戏 + 实景的拍摄方式，效果非常好。尤其游戏内拍摄的部分，几乎是由原作者所在的工会玩家们齐心协力共同制作完成的。</p><p><a href="https://www.netflix.com/jp/title/80178543" target="_blank" rel="noreferrer">网飞 (Netflix) 版 (自带简中字幕)</a>，<a href="https://www.diyidan.com/main/post/6294360860192592995/detail/1" target="_blank" rel="noreferrer">[拉拉菲尔保护协会] 字幕组自制版 (需要下载 APP 才能看)</a></p><p>另外我在得知有这么个连载之后就跑去原博看完了所有连载… 实际上… 连续剧改动还是挺大的 (比如不存在的女主角… 毕竟有各种各样的原因)</p><p>贴吧有大佬做了光之老爹的翻译→[<a href="https://tieba.baidu.com/p/6056620931?see_lz=1" target="_blank" rel="noreferrer">阅读光之老爹连载传送门</a>]</p><h2 id="玩家自制电影" tabindex="-1">玩家自制电影</h2><p>FF14 丰富的情感动作和强大的拍摄滤镜功能，帮助玩家们可以在游戏里拍摄电影。上面提到的光之老爹电影，也是由真人实拍穿插游戏内拍摄完成的，无论是动作画面表演、对口型，或是各种场景表演，配合天气、时间的变化，几乎可以拍出任何可能。</p><p>由 TOI TOI 制作的<a href="https://www.bilibili.com/video/av28612727" target="_blank" rel="noreferrer"> FFXIV 国际服 5 周年纪念短片集 &#39;LIGHTPARTY&#39;</a>(授权搬运，评论中有更多信息)，<a href="https://www.bilibili.com/video/av61945692" target="_blank" rel="noreferrer">FFXIV 国际服 6 周年纪念短片 &#39; ミニオンの大冒険&#39;</a> 是其中翘楚。</p><h2 id="纪录片" tabindex="-1">纪录片</h2>',26)),s(r,{file:"_includes/history/documentary.md"}),e[1]||(e[1]=t("h2",{id:"其他",tabindex:"-1"},"其他",-1)),e[2]||(e[2]=t("ul",null,[t("li",null,[t("a",{href:"https://space.bilibili.com/689413/channel/collectiondetail?sid=462444",target:"_blank",rel:"noreferrer"},"FF14 名曲鉴赏 - 起源篇（昔日的答案）"),l("：FF14 1.0 版本音乐鉴赏合辑（视频）")]),t("li",null,[t("a",{href:"https://space.bilibili.com/689413/channel/collectiondetail?sid=516528",target:"_blank",rel:"noreferrer"},"FF14 名曲鉴赏 - 新生篇（涅槃的乐章）"),l("：FF14 2.0 版本音乐鉴赏合辑（视频）")])],-1))])}const k=i(p,[["render",d]]);export{g as __pageData,k as default};
